import csv
from pathlib import Path


def main(file_path: str):
    print(f"[read_csv] START file_path={file_path}")
    path = Path(file_path)
    if not path.exists():
        print(f"[read_csv] ERROR file not found on worker: {file_path}")
        raise FileNotFoundError(f"CSV not visible to windmill worker: {file_path}")

    raw_rows = []
    with path.open("r", encoding="utf-8", newline="") as fh:
        for row in csv.DictReader(fh):
            raw_rows.append(dict(row))

    print(f"[read_csv] OK read {len(raw_rows)} rows from {path.name}")
    if raw_rows:
        print(f"[read_csv] columns detected: {list(raw_rows[0].keys())}")
    return {"file_path": file_path, "raw_rows": raw_rows, "row_count": len(raw_rows)}

def main(read_result: dict):
    raw_rows = read_result["raw_rows"]
    print(f"[transform_rows] START received {len(raw_rows)} raw rows")

    allowed = {"finance", "hr", "sales"}
    valid_rows = []
    skipped = []
    for idx, row in enumerate(raw_rows):
        dept = (row.get("department") or "").strip().lower()
        if dept not in allowed:
            print(f"[transform_rows] SKIP row {idx} - invalid department: {dept!r}")
            skipped.append({"row_index": idx, "reason": f"invalid department {dept!r}"})
            continue
        try:
            clean = {
                "department": dept,
                "source_row_id": int(row["id"]),
                "employee_name": row["employee_name"].strip(),
                "amount": row["amount"],
                "record_date": row["date"],
            }
        except (KeyError, ValueError) as exc:
            print(f"[transform_rows] SKIP row {idx} - parse error: {exc}")
            skipped.append({"row_index": idx, "reason": str(exc)})
            continue
        valid_rows.append(clean)

    print(f"[transform_rows] OK normalized={len(valid_rows)} skipped={len(skipped)}")
    return {
        "valid_rows": valid_rows,
        "valid_count": len(valid_rows),
        "skipped_count": len(skipped),
        "skipped": skipped,
    }

def main(transform_result: dict):
    valid_rows = transform_result["valid_rows"]
    print(f"[distribute] START distributing {len(valid_rows)} rows by department")

    buckets = {"finance": [], "hr": [], "sales": []}
    for row in valid_rows:
        buckets[row["department"]].append(row)

    counts = {dept: len(rows) for dept, rows in buckets.items()}
    for dept, n in counts.items():
        print(f"[distribute] department '{dept}' -> {n} rows")
    print(f"[distribute] OK total distributed={sum(counts.values())}")
    return {"buckets": buckets, "counts": counts}
